parameters.jsCode:
// Extract and normalize data from dispatch-report-webhook payload
const body = $json.body || $json;

// Safe string: null-safe + truncate to ManyChat's 1000-char text field limit
const s = (val, max = 1000) => (val == null ? '' : String(val).trim().slice(0, max));

const leadPhone = s(body.lead_phone).replace(/[^0-9]/g, '');
const leadEmail = s(body.lead_email);
const leadName  = s(body.lead_name);

const tempMap = {
  'frio': 'Frio',
  'morno': 'Morno',
  'quente': 'Quente',
  'muito-quente': 'Muito Quente',
};

const phaseMap = {
  0: 'Base Insuficiente',
  1: 'Preparação Estruturada',
  2: 'Tração Ativa',
  3: 'Aceleração',
};

return [{
  json: {
    // Identity
    lead_phone: leadPhone,
    lead_email: leadEmail,
    lead_name: leadName,
    first_name: leadName.split(' ')[0] || leadName,
    report_link: s(body.report_link),
    // User data (raw form answers)
    area: s(body.area),
    atuacao: s(body.atuacao),
    experiencia: s(body.experiencia),
    english_level: s(body.english_level),
    objetivo: s(body.objetivo),
    visa_status: s(body.visa_status),
    timeline: s(body.timeline),
    family_status: s(body.family_status),
    income_range: s(body.income_range),
    investment_range: s(body.investment_range),
    impediment: s(body.impediment),
    main_concern: s(body.main_concern),
    // AI-generated scoring & qualification
    readiness_score: body.readiness_score ?? '',
    lead_temperature: tempMap[body.lead_temperature] || s(body.lead_temperature),
    lead_priority_score: body.lead_priority_score ?? '',
    phase_name: s(body.phase_name) || (phaseMap[body.phase_id] || ''),
    full_diagnosis: s(body.full_diagnosis),
    recommended_product_tier: s(body.recommended_product_tier),
    primary_product: s(body.primary_product),
    is_tech_professional: body.is_tech_professional || false,
    is_senior_level: body.is_senior_level || false,
    is_high_income: body.is_high_income || false,
    barriers: Array.isArray(body.barriers) ? body.barriers.join(', ').slice(0, 1000) : '',
    source: body.source || 'enp_hub_supabase',
    event: body.event || 'report.generated',
  }
}];

